# The ledger types whose sum, capped by the credit value, was the withdrawable
# balance before lots existed.
WITHDRAWABLE_TYPES = (
    "affiliate_fee",
    "transfer_in",
    "transfer_out",
    "payout",
    "withdrawable_adjustment",
)


def create_lots(apps, schema_editor):
    """Split every existing balance into an earned lot (what was withdrawable)
    and a granted lot (the rest), so balances, withdrawable balances and
    affiliate fees stay as they were until staff record or reclassify paid
    credit."""
    CustomerCredit = apps.get_model("invoices", "CustomerCredit")
    CreditTransaction = apps.get_model("invoices", "CreditTransaction")
    CreditLot = apps.get_model("invoices", "CreditLot")

    for credit in CustomerCredit.objects.filter(value__gt=0).iterator():
        earned = CreditTransaction.objects.filter(
            credit=credit, transaction_type__in=WITHDRAWABLE_TYPES
        ).aggregate(sum=Sum("amount"))["sum"] or decimal.Decimal("0")
        earned = max(decimal.Decimal("0"), min(earned, credit.value))
        granted = credit.value - earned
        CreditLot.objects.bulk_create(
            CreditLot(credit=credit, kind=kind, amount=amount, remaining=amount)
            for kind, amount in (("earned", earned), ("granted", granted))
            if amount
        )


